  /**
   * @method
   * @name mercado#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of open order structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchOpenOrders() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("coin_pair"),
                      ::getValue(market, std::string("id"))},
                     {std::string("status_list"), std::string("[2]")},
                 };
                 ccxt::any response = awaitValue(this->privatePostListOrders(
                     this->extend(request, params)));
                 ccxt::any responseData = this->safeValue(
                     response, std::string("response_data"), ccxt::dict{});
                 ccxt::any orders = this->safeList(
                     responseData, std::string("orders"), ccxt::list{});
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name mercado#fetchMyTrades
   * @description fetch all trades made by the user
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(
                           " fetchMyTrades() requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("coin_pair"),
                      ::getValue(market, std::string("id"))},
                     {std::string("has_fills"), true},
                 };
                 ccxt::any response = awaitValue(this->privatePostListOrders(
                     this->extend(request, params)));
                 ccxt::any responseData = this->safeValue(
                     response, std::string("response_data"), ccxt::dict{});
                 ccxt::any ordersRaw = this->safeValue(
                     responseData, std::string("orders"), ccxt::list{});
                 ccxt::any orders =
                     this->parseOrders(ordersRaw, market, since, limit);
                 ccxt::any trades = this->ordersToTrades(orders);
                 return this->filterBySymbolSinceLimit(
                     trades, ::getValue(market, std::string("symbol")), since,
                     limit);
               })
        .share();
  }

  virtual ccxt::any ordersToTrades(ccxt::any orders) {
    ccxt::any result = ccxt::list{};
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(orders));
         postFixIncrement(i)) {
      ccxt::any trades = this->safeValue(::getValue(orders, i),
                                         std::string("trades"), ccxt::list{});
      for (ccxt::any y = 0; isLessThan(y, getArrayLength(trades));
           postFixIncrement(y)) {
        arrayPush(result, ::getValue(trades, y));
      }
    }
    return result;
  }

  ccxt::any sign(ccxt::any path, ccxt::any api = std::string("public"),
                 ccxt::any method = std::string("GET"),
                 ccxt::any params = ccxt::dict{},
                 ccxt::any headers = ccxt::any{},
                 ccxt::any body = ccxt::any{}) override {
    ccxt::any url =
        add(::getValue(::getValue(this->urls, std::string("api")), api),
            std::string("/"));
    ccxt::any query = this->omit(params, this->extractParams(path));
    if (isTrue(isTrue(isTrue((isEqual(api, std::string("public")))) ||
                      isTrue((isEqual(api, std::string("v4Public"))))) ||
               isTrue((isEqual(api, std::string("v4PublicNet")))))) {
      url = add(url, this->implodeParams(path, params));
      if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(query)), 0))) {
        url = add(url, add(std::string("?"), this->urlencode(query)));
      }
    } else {
      this->checkRequiredCredentials();
      url = add(url, add(this->version, std::string("/")));
      ccxt::any nonce = this->nonce();
      body = this->urlencode(this->extend(
          ccxt::dict{
              {std::string("tapi_method"), path},
              {std::string("tapi_nonce"), nonce},
          },
          params));
      ccxt::any auth = add(
          add(add(add(std::string("/tapi/"), this->version), std::string("/")),
              std::string("?")),
          body);
      headers = ccxt::dict{
          {std::string("Content-Type"),
           std::string("application/x-www-form-urlencoded")},
          {std::string("TAPI-ID"), this->apiKey},
          {std::string("TAPI-MAC"),
           this->hmac(this->encode(auth), this->encode(this->secret), sha512)},
      };
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  ccxt::any handleErrors(ccxt::any httpCode, ccxt::any reason, ccxt::any url,
                         ccxt::any method, ccxt::any headers, ccxt::any body,
                         ccxt::any response, ccxt::any requestHeaders,
                         ccxt::any requestBody) override {
    if (isTrue(isEqual(response, ccxt::any{}))) {
      return ccxt::any{};
    }
    //
    // todo add a unified standard handleErrors with this.exceptions in
    // describe()
    //
    //     {"status":503,"message":"Maintenancing, try again
    //     later","result":null}
    //
    ccxt::any errorMessage =
        this->safeValue(response, std::string("error_message"));
    if (isTrue(!isEqual(errorMessage, ccxt::any{}))) {
      throw ExchangeError(
          toString(add(add(this->id, std::string(" ")), this->json(response))));
    }
    return ccxt::any{};
  }
